    Terna(int primero, int segundo, int tercero) : datos_{primero, segundo, tercero} {}
    int& operator[](int indice);
    const int& operator[](int indice) const;
    void escribir(std::ostream& salida) const {
        salida << datos_[0] << ':' << datos_[1] << ':' << datos_[2];
    }
private:
    int datos_[3]{10, 20, 30};
};

int& Terna::operator[](int indice) {
    // Comprueba el índice y devuelve una referencia al elemento elegido.
    (void)indice;
    return datos_[0];
}

const int& Terna::operator[](int indice) const {
    // Comprueba también el acceso constante, sin permitir escribir por el retorno.
    (void)indice;
    return datos_[0];
}

int main() {
    int ordenes = 0;
    if (!(std::cin >> ordenes) || ordenes < 1 || ordenes > 12) { return 1; }
    Terna datos;
    const Terna& lectura = datos;
    int* enlace = &datos[0];
    const int* observado = &lectura[2];

    for (int i = 0; i < ordenes; ++i) {
        int op = 0, indice = 0, valor = 0;
        if (!(std::cin >> op >> indice >> valor)) { return 1; }
        std::cout << "Antes:";
        datos.escribir(std::cout);
        const char* estado = "Aceptada";
        int resultado = 0;
        try {
            if (op == 1) { int& r = datos[indice]; resultado = r; }
            else if (op == 2) { const int& r = lectura[indice]; resultado = r; }
            else if (op == 3) { datos[indice] = valor; resultado = valor; }
            else if (op == 4) { enlace = &datos[indice]; resultado = *enlace; }
            else if (op == 5) { *enlace = valor; resultado = *enlace; }
            else if (op == 6) { observado = &lectura[indice]; resultado = *observado; }
            else { estado = "Operacion"; }
        } catch (const IndiceFuera&) { estado = "Indice"; }
        std::cout << ";Estado:" << estado << ";Dato:" << resultado
                  << ";Enlace:" << *enlace << ";Visto:" << *observado << ";Ahora:";
        datos.escribir(std::cout);
        std::cout << '\n';
    }
    std::cout << "Final:";
    datos.escribir(std::cout);
    return 0;
}

